use super::*;
#[semio_framework_async_macros::async_test]
async fn neutral_normative_catalog_queries(){let catalog=ifc4_catalog();let vectors=semio_framework_pack_json::parse(include_str!("🔣️.json"),semio_framework_pack_json::JsonMemberPolicy::Reject).unwrap();assert_eq!(catalog.schema,"IFC4");assert_eq!(catalog.version,"4.0.2.1");assert_eq!(catalog.entities.len(),776);assert_eq!(catalog.types.len(),397);assert_eq!(catalog.functions.len(),47);assert_eq!(catalog.rules.len(),2);assert_eq!(catalog.types.values().filter(|t|t.kind=="enum").count(),207);assert_eq!(catalog.types.values().filter(|t|t.kind=="select").count(),60);for row in vectors["subtypes"].as_array().unwrap(){assert_eq!(ifc4_is_subtype(row[0].as_str().unwrap(),row[1].as_str().unwrap()),row[2].as_bool().unwrap());}for row in vectors["attributes"].as_array().unwrap(){let attribute=ifc4_attribute(row["entity"].as_str().unwrap(),row["index"].as_u64().unwrap() as usize).unwrap();assert_eq!(attribute.name,row["name"].as_str().unwrap());assert_eq!(attribute.type_expr.name.as_deref(),row["type"].as_str());assert_eq!(attribute.optional,row["optional"].as_bool().unwrap());assert_eq!(attribute.derived,row["derived"].as_bool().unwrap());}for row in vectors["enums"].as_array().unwrap(){let expected:Vec<String>=row["members"].as_array().unwrap().iter().map(|v|v.as_str().unwrap().into()).collect();assert_eq!(ifc4_enum_members(row["name"].as_str().unwrap()).unwrap(),expected.as_slice());}for row in vectors["selects"].as_array().unwrap(){for member in row["accepts"].as_array().unwrap(){assert!(ifc4_select_accepts(row["name"].as_str().unwrap(),member.as_str().unwrap()));}for member in row["rejects"].as_array().unwrap(){assert!(!ifc4_select_accepts(row["name"].as_str().unwrap(),member.as_str().unwrap()));}}let expression=IfcTypeExpression{kind:"named".into(),name:Some("IFCPOSITIVELENGTHMEASURE".into()),..Default::default()};assert_eq!(ifc4_resolve_type(&expression).unwrap().name.as_deref(),Some("REAL"));assert!(catalog.entities.values().all(|e|!e.supertype_expression.is_empty()||e.supertype.is_none()));}
#[semio_framework_async_macros::async_test]
async fn independent_ifcopenshell_metadata_matches_all_named_declarations(){let reference=semio_framework_pack_json::parse(include_str!("ifcopenshell-reference.json"),semio_framework_pack_json::JsonMemberPolicy::Reject).unwrap();let catalog=ifc4_catalog();assert_eq!(reference["entities"].as_object().unwrap().len(),catalog.entities.len());for(name,entity)in reference["entities"].as_object().unwrap().iter(){let own=catalog.entities.get(&name.to_ascii_uppercase()).unwrap();for attribute in entity["attributes"].as_array().unwrap(){let attr=attribute.as_str().unwrap();assert!(own.all_attributes.iter().any(|a|a.name==attr)||own.derived.iter().any(|a|a.name==attr)||own.inverse.iter().any(|a|a.split(|c:char|!c.is_alphanumeric()&&c!='_').next()==Some(attr)));}}assert_eq!(reference["types"].as_array().unwrap().len(),catalog.types.len());for name in reference["types"].as_array().unwrap(){assert!(catalog.types.contains_key(&name.as_str().unwrap().to_ascii_uppercase()));}}
